    cu = uy + uz
    fn[15, x, y, z] = F(0.027777777777777776) * rho * (F(1.0) + F(3.0) * cu + F(4.5) * cu * cu - usq) + om1 * F(0.125) * (Nyy + Nzz + (2*Nyz) - tr * F(0.3333333333333333)) + F(0.125) * trb
    cu = - uy - uz
